INSERT INTO `document` VALUES (2, 0, 0, 82001, 'APIJSON.cn', 0, 1, NULL, '注册(先获取验证码type:1)', 'REGISTER', 'POST', 'JSON', '/register', '{\n    \"Privacy\": {\n        \"phone\": 13000083333,\n        \"_password\": \"123456\"\n    },\n    \"User\": {\n        \"name\": \"APIJSONUser\"\n    },\n    \"verify\": \"6840\"\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"Privacy\": {\n                \"notnull\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"phone\": {\n                            \"notnull\": true,\n                            \"type\": \"integer\",\n                            \"valueLevel\": 3,\n                            \"values\": [],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                11\n                            ],\n                            \"comment\": \"手机号\"\n                        },\n                        \"_password\": {\n                            \"notnull\": true,\n                            \"type\": \"string\",\n                            \"valueLevel\": 3,\n                            \"values\": [],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                6\n                            ]\n                        }\n                    }\n                ],\n                \"comment\": \"用户隐私信息\"\n            },\n            \"User\": {\n                \"notnull\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"name\": {\n                            \"notnull\": true,\n                            \"type\": \"string\",\n                            \"valueLevel\": 3,\n                            \"values\": [],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                11\n                            ]\n                        }\n                    }\n                ],\n                \"comment\": \"用户常规信息\"\n            },\n            \"verify\": {\n                \"notnull\": true,\n                \"type\": \"string\",\n                \"valueLevel\": 3,\n                \"values\": [],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    4\n                ],\n                \"comment\": \"验证码，需要先调用接口 /post/verify\"\n            }\n        }\n    ]\n}', '', '2017-11-26 15:35:19', NULL);
