INSERT INTO `document` VALUES (1511796155276, 0, 0, 82001, 'APIJSON.cn', 0, 1, NULL, '获取验证码', 'POST_VERIFY', 'POST', 'JSON', '/post/verify', '{\n    \"type\": 0,\n    \"phone\": \"13000082001\"\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"type\": {\n                \"notnull\": true,\n                \"type\": \"integer\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    0\n                ],\n                \"lengthLevel\": 1,\n                \"lengths\": [],\n                \"comment\": \"类型: 0-登录 1-注册 2-修改登录密码 3-修改支付密码\"\n            },\n            \"phone\": {\n                \"notnull\": true,\n                \"type\": \"string\",\n                \"valueLevel\": 3,\n                \"values\": [],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    11\n                ],\n                \"comment\": \"手机号\"\n            }\n        }\n    ]\n}', '', '2017-11-27 23:23:28', NULL);
INSERT INTO `document` VALUES (1511796208671, 0, 0, 82001, 'APIJSON.cn', 0, 1, NULL, '检查验证码是否存在', 'HEADS_VERIFY', 'POST', 'JSON', '/heads/verify', '{\n    \"type\": 0,\n    \"phone\": \"13000082001\"\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"type\": {\n                \"notnull\": true,\n                \"type\": \"integer\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    0\n                ],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    1\n                ],\n                \"comment\": \"类型: 0-登录 1-注册 2-修改登录密码 3-修改支付密码\",\n                \"trend\": {\n                    \"top\": 7\n                }\n            },\n            \"phone\": {\n                \"notnull\": true,\n                \"type\": \"string\",\n                \"valueLevel\": 3,\n                \"values\": [],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    11\n                ],\n                \"comment\": \"手机号\"\n            }\n        }\n    ]\n}', '', '2017-11-27 23:23:28', NULL);
INSERT INTO `document` VALUES (1511796589078, 0, 0, 82001, 'APIJSON.cn', 82001, 1, NULL, '修改登录密码(先获取验证码type:2)-手机号+验证码', 'PUT_PASSWORD', 'POST', 'JSON', '/put/password', '{\n    \"verify\": \"10322\",\n    \"Privacy\": {\n        \"phone\": \"13000082001\",\n        \"_password\": \"666666\"\n    }\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"verify\": {\n                \"notnull\": true,\n                \"type\": \"string\",\n                \"valueLevel\": 3,\n                \"values\": [],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    5\n                ],\n                \"comment\": \"验证码，需要先调用接口 /post/verify\"\n            },\n            \"Privacy\": {\n                \"notnull\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"phone\": {\n                            \"notnull\": true,\n                            \"type\": \"string\",\n                            \"valueLevel\": 3,\n                            \"values\": [],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                11\n                            ]\n                        },\n                        \"_password\": {\n                            \"notnull\": true,\n                            \"type\": \"string\",\n                            \"valueLevel\": 3,\n                            \"values\": [],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                6\n                            ]\n                        }\n                    }\n                ]\n            }\n        }\n    ]\n}', '', '2017-11-27 23:23:28', NULL);
