INSERT INTO `document` VALUES (1521901610784, 0, 0, 88888, NULL, 0, 2, NULL, '功能符(对象关键词): ④查询 按userId分组、id最大值>=100 的Moment数组', 'SELECT', 'POST', 'JSON', '/get', '{\n    \"[]\": {\n        \"count\": 10,\n        \"Moment\": {\n            \"@column\": \"userId;max(id):maxId\",\n            \"@group\": \"userId\",\n            \"@having\": \"(maxId)>=100\"\n        }\n    }\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"[]\": {\n                \"notnull\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"count\": {\n                            \"notnull\": true,\n                            \"type\": \"integer\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                10\n                            ],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                2\n                            ]\n                        },\n                        \"Moment\": {\n                            \"notnull\": true,\n                            \"type\": \"object\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                {\n                                    \"@column\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            20\n                                        ]\n                                    },\n                                    \"@group\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            6\n                                        ]\n                                    },\n                                    \"@having\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            12\n                                        ]\n                                    }\n                                }\n                            ]\n                        }\n                    }\n                ]\n            }\n        }\n    ]\n}', '', '2018-03-24 22:26:50', NULL);
