INSERT INTO `document` VALUES (1521907333043, 0, 0, 88888, NULL, 82002, 3, NULL, '微信个人资料-用户信息+最近3个有照片的动态的第0张照片', 'SELECT', 'POST', 'JSON', '/get', '{\n    \"User\": {\n        \"id\": 82002\n    },\n    \"Moment-firstPicture[]\": {\n        \"count\": 3,\n        \"Moment\": {\n            \"userId@\": \"User/id\",\n            \"@column\": \"pictureList\",\n            \"@having\": \"json_length(pictureList)>0\",\n            \"firstPicture()\": \"getFromArray(pictureList,0)\"\n        }\n    }\n}', NULL, NULL, NULL, NULL, '2018-03-25 00:03:13', NULL);
