INSERT INTO `document` VALUES (1544881887527, 0, 0, 88888, NULL, 0, 3, NULL, 'Moment INNER JOIN User LEFT JOIN Comment', 'SELECT', 'POST', 'JSON', '/get', '{\n    \"[]\": {\n        \"count\": 10,\n        \"page\": 0,\n        \"join\": \"&/User/id@,</Comment/momentId@\",\n        \"Moment\": {\n            \"@order\": \"date+\"\n        },\n        \"User\": {\n            \"name~\": [\n                \"a\",\n                \"t\"\n            ],\n            \"id@\": \"/Moment/userId\",\n            \"@column\": \"id,name,head\"\n        },\n        \"Comment\": {\n            \"momentId@\": \"/Moment/id\",\n            \"@column\": \"id,momentId,content\"\n        }\n    }\n}', NULL, NULL, NULL, NULL, '2018-12-15 21:51:27', NULL);
