s\": [],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    6\n                ]\n            },\n            \"version\": {\n                \"notnull\": false,\n                \"type\": \"integer\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    1\n                ],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    1\n                ]\n            },\n            \"remember\": {\n                \"notnull\": false,\n                \"type\": \"boolean\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    false\n                ],\n                \"lengthLevel\": 1,\n                \"lengths\": []\n            },\n            \"format\": {\n                \"notnull\": false,\n                \"type\": \"boolean\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    false\n                ],\n                \"lengthLevel\": 1,\n                \"lengths\": []\n            },\n            \"defaults\": {\n                \"notnull\": false,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"@database\": {\n                            \"notnull\": true,\n                            \"type\": \"string\",\n                            \"valueLevel\": 0,\n                            \"format\": \"NAME:Big\",\n                            \"values\": [\n                                \"MYSQL\"\n                            ],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                5\n                            ]\n                        },\n                        \"@schema\": {\n                            \"notnull\": true,\n                            \"type\": \"string\",\n                            