INSERT INTO `document` VALUES (1559995734352, 0, 0, 82001, 'APIJSON.cn', 0, 3, NULL, 'get 自定义关键词和远程函数的应用', 'SELECT', 'POST', 'JSON', '/get', '{\n    \"User\": {\n        \"id\": 82001,\n        \"@column\": \"contactIdList\",\n        \"@value\": 82006,\n        \"isPraise()\": \"isContain(contactIdList,@value)\"\n    }\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"User\": {\n                \"notnull\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"id\": {\n                            \"notnull\": true,\n                            \"type\": \"integer\",\n                            \"valueLevel\": 1,\n                            \"values\": [\n                                82001\n                            ],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                5\n                            ],\n                            \"trend\": {\n                                \"top\": 4\n                            },\n                            \"comment\": \"主键\"\n                        },\n                        \"@column\": {\n                            \"notnull\": true,\n                            \"type\": \"string\",\n                            \"valueLevel\": 3,\n                            \"values\": [],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                13\n                            ]\n                        },\n                        \"@value\": {\n                            \"notnull\": true,\n                            \"type\": \"integer\",\n                            \"valueLevel\": 1,\n                            \"values\": [\n                                82006\n                            ],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                5\n                            ],\n                            \"trend\": {\n                                \"top\": 4\n                            },\n                            \"comment\": \"自定义关键词\"\n                        },\n                        \"isContect()\": {\n                            \"notnull\": false,\n                            \"type\": \"string\",\n                            \"valueLevel\": 3,\n                            \"values\": [],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                31\n                            ]\n                        },\n                        \"isPraise()\": {\n                            \"notnull\": true,\n                            \"type\": \"string\",\n                            \"valueLevel\": 3,\n                            \"values\": [],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                31\n                            ]\n                        }\n                    }\n                ]\n            }\n        }\n    ]\n}', '', '2019-06-08 20:08:54', '\n1、获取User表中的id==82001的数据块；\n2、获取contactIdList列中的数据；\n3、设定自定义关键词和值\"@value\": 82006；\n4、调用远程函数isContain判断 contactIdList 中是否存在值为82006的id；\n5、判断结果看 isContect的值。');
