INSERT INTO `document` VALUES (1567927050590, 0, 0, 88888, NULL, 0, 3, NULL, 'test response hint', 'SELECT', 'POST', 'JSON', '/get', '{\n    \"[]\": {\n        \"count\": 5,\n        \"page\": 0,\n        \"Moment\": {\n            \"@order\": \"date+\"\n        },\n        \"User\": {\n            \"id@\": \"/Moment/userId\",\n            \"@column\": \"id,name,head\"\n        },\n        \"User[]\": {\n            \"count\": 10,\n            \"query\": 2,\n            \"User\": {\n                \"id{}@\": \"[]/Moment/praiseUserIdList\",\n                \"@column\": \"id,name\"\n            }\n        },\n        \"Comment-userId[]\": {\n            \"count\": 6,\n            \"query\": 2,\n            \"Comment\": {\n                \"@order\": \"date+\",\n                \"momentId@\": \"[]/Moment/id\"\n            }\n        },\n        \"praiseCount@\": \"/User[]/total\",\n        \"commentCount@\": \"/Comment-userId[]/total\"\n    }\n}', NULL, NULL, NULL, '', '2019-09-08 15:17:30', NULL);
INSERT INTO `document` VALUES (1572174664812, 0, 0, 88888, NULL, 0, 3, NULL, '部分功能总览', 'SELECT', 'POST', 'JSON', '/get', '{\n    \"[]\": {\n        \"count\": 5,\n        \"page\": 0,\n        \"join\": \"</User/id@\",\n        \"Moment\": {\n            \"@order\": \"date+\",\n            \"@column\": \"id,userId;date_format(date,%Y-%m-%d %H:%m)\",\n            \"@explain\": true,\n            \"content~\": \"o\",\n            \"userId!\": 82001,\n            \"@combine\": \"userId!,content~\"\n        },\n        \"User\": {\n            \"id@\": \"/Moment/userId\",\n            \"@column\": \"id,name,head\"\n        },\n        \"[]\": {\n            \"count\": 6,\n            \"join\": \"@/User/id@\",\n            \"Comment\": {\n                \"@order\": \"date-\",\n                \"momentId@\": \"[]/Moment/id\"\n            },\n            \"User\": {\n                \"id@\": \"/Comment/userId\",\n                \"@column\": \"DISTINCT id,name;concat(\'%\',name,\'%\'):concat\"\n            }\n        }\n    }\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"[]\": {\n                \"notnull\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"count\": {\n                            \"notnull\": true,\n                            \"type\": \"integer\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                5\n                            ],\n                            \"lengthLevel\": 1,\n                            \"lengths\": []\n                        },\n                        \"page\": {\n                            \"notnull\": true,\n                            \"type\": \"integer\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n    