                                     \"notnull\": true,\n                                        \"type\": \"boolean\",\n                                        \"valueLevel\": 0,\n                                        \"values\": [\n                                            true\n                                        ],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": []\n                                    },\n                                    \"content~\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            1\n                                        ]\n                                    },\n                                    \"userId!\": {\n                                        \"notnull\": true,\n                                        \"type\": \"integer\",\n                                        \"valueLevel\": 1,\n                                        \"values\": [\n                                            82001\n                                        ],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": []\n                                    },\n                                    \"@combine\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                  