true,\n                                        \"type\": \"integer\",\n                                        \"valueLevel\": 0,\n                                        \"values\": [\n                                            6\n                                        ],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": []\n                                    },\n                                    \"join\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            10\n                                        ]\n                                    },\n                                    \"Comment\": {\n                                        \"notnull\": true,\n                                        \"type\": \"object\",\n                                        \"valueLevel\": 0,\n                                        \"values\": [\n                                            {\n                                                \"@order\": {\n                                                    \"notnull\": true,\n                                                    \"type\": \"string\",\n                                                    \"valueLevel\": 3,\n                                                    \"values\": [],\n                                                    \"lengthLevel\": 1,\n                                                    \"lengths\": [\n                                                        5\n                                                    ]\n                                                },\n                                 