INSERT INTO `document` VALUES (1602231365650, 0, 0, 2020, NULL, 0, 3, NULL, 'JOIN 对象支持包含多个 @ 引用赋值 的字段', 'SELECT', 'POST', 'JSON', '/get', '{   // 自动合并  ON Method.class = `Method:group`.class AND Method.package = `Method:group`.package\n    \"Method[]\": {\n        \"count\": 0,\n        \"join\": \"@/Method/class@,@/Method/package@\",\n        \"Method:group\": {\n            \"@column\": \"DISTINCT class\",\n            \"@order\": \"class+\",\n            \"@having\": \"length(class)>0\",\n            \"package*~\": null,\n            \"class*~\": null,\n            \"@combine\": null\n        },\n        \"Method\": {\n            \"package@\": \"[]/Method/package\",\n            \"class@\": \"/Method:group/class\",\n            \"@column\": \"class,genericClassArgs\",\n            \"@order\": \"class+\",\n            \"arguments()\": \"getMethodArguments(genericClassArgs)\"\n        }\n    }\n}\n                                                                                                                                                                                                              \n', NULL, NULL, NULL, '', '2020-10-09 16:16:05', NULL);
