INSERT INTO `document` VALUES (1654148705805, 0, 0, 82031, NULL, 0, 3, NULL, '多字段参与join，是否出现1+N查询', 'SELECT', 'POST', 'JSON', '/get', '{\n    \"[]\": {\n        \"count\": 10,\n        \"page\": 0,\n        \"join\": \"&/User/id@,</Comment\",\n        \"Moment\": {\n            \"@order\": \"date+\"\n        },\n        \"User\": {\n            \"name~\": [\n                \"a\",\n                \"t\"\n            ],\n            \"id@\": \"/Moment/userId\",\n            \"@column\": \"id,name,head\"\n        },\n        \"Comment\": {\n            \"momentId@\": \"/Moment/id\",\n            \"userId@\": \"/Moment/userId\",\n            \"@column\": \"id,userId,momentId,content\"\n        },\n        \"@explain\": true\n    }\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"[]\": {\n                \"notnull\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"count\": {\n                            \"notnull\": true,\n                            \"type\": \"integer\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                10\n                            ],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                2\n                            ],\n                            \"trend\": {\n                                \"top\": 3\n                            }\n                        },\n                        \"page\": {\n                            \"notnull\": true,\n                            \"type\": \"integer\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                0\n                            ],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                1\n                            ],\n                            \"trend\": {\n                                \"top\": 3\n                            }\n                        },\n                        \"join\": {\n                            \"notnull\": true,\n                            \"type\": \"string\",\n                            \"valueLevel\": 3,\n                            \"values\": [],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                20\n                            ]\n                        },\n                        \"Moment\": {\n                            \"notnull\": true,\n                            \"type\": \"object\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                {\n                                    \"@order\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            5\n                                        ]\n                                    }\n                                }\n                            ]\n                        },\n                        \"User\": {\n                            \"notnull\": true,\n                            \"type\": \"object\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                {\n                                    \"name~\": {\n                                        \"notnull\": true,\n                                        \"type\": \"array\",\n                                        \"valueLevel\": 0,\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            2\n                                        ],\n                                        \"values\": [\n                                            {\n                                                \"notnull\": true,\n                                                \"type\": \"string\",\n                                                \"valueLevel\": 3,\n                                                \"values\": [],\n                                                \"lengthLevel\": 1,\n                                                \"lengths\": [\n                                                    1\n                                                ]\n                                            }\n                                        ]\n                                    },\n                                    \"id@\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            14\n                                        ]\n                                    },\n                                    \"@column\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            12\n                                        ]\n                                    }\n                                }\n                            ]\n                        },\n                        \"Comment\": {\n                            \"notnull\": true,\n                            \"type\": \"object\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                {\n                                    \"momentId@\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            10\n                                        ]\n                                    },\n                                    \"userId@\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            14\n                                        ]\n                                    },\n                                    \"@column\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            26\n                                        ]\n                                    }\n                                }\n                            ]\n                        },\n                        \"@explain\": {\n                            \"notnull\": true,\n                            \"type\": \"boolean\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                true\n                            ],\n                            \"lengthLevel\": 1,\n                            \"lengths\": []\n                        }\n                    }\n                ],\n                \"comment\": \"查列表，每页10条\"\n            },\n            \"@explain\": {\n                \"notnull\": false,\n                \"type\": \"boolean\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    true\n                ],\n                \"lengthLevel\": 1,\n                \"lengths\": []\n            }\n        }\n    ]\n}', '', '2022-06-02 13:45:05', NULL);
INSERT INTO `document` VALUES (1657045372046, 0, 0, 82031, NULL, 0, 3, NULL, '一对多关联查询 Comment.userId = User.id', 'SELECT', 'POST', 'JSON', '/get', '{\n    \"User\": {\n        \"id\": 82001\n    },\n    \"[]\": {\n        \"Comment\": {\n            \"userId@\": \"User/id\"\n        }\n    }\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"User\": {\n                \"notnull\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"id\": {\n                            \"notnull\": false,\n                            \"type\": \"integer\",\n                            \"valueLevel\": 1,\n                            \"values\": [\n                                82001\n                            ],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                5\n                            ],\n                            \"trend\": {\n                                \"top\": 1\n                            }\n                        },\n                        \"id@\": {\n                            \"notnull\": false,\n                            \"type\": \"string\",\n                            \"valueLevel\": 3,\n                            \"values\": [],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                14\n                            ]\n                        }\n                    }\n                ]\n            },\n            \"[]\": {\n                \"notnull\": false,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"Comment\": {\n                            \"notnull\": true,\n                            \"type\":