INSERT INTO `document` VALUES (1657811332517, 0, 0, 88888, NULL, 0, 3, NULL, '跨级 APP JOIN', 'SELECT', 'POST', 'JSON', '/get', '{\n    \"[]\": {\n        \"count\": 2,\n        \"join\": \"@/User,@/Comment[]/Comment/momentId@\",\n        \"Moment\": {},\n        \"User\": {\n            \"id@\": \"/Moment/userId\",\n            \"@column\": \"id,head\"\n        },\n        \"Comment[]\": {\n            \"count\": 3,\n            \"Comment\": {\n                \"momentId@\": \"[]/Moment/id\"\n            }\n        }\n    }\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"[]\": {\n                \"notnull\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"count\": {\n                            \"notnull\": true,\n                            \"type\": \"integer\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                2\n                            ],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                1\n                            ]\n                        },\n                        \"join\": {\n                            \"notnull\": true,\n                            \"type\": \"string\",\n                            \"valueLevel\": 3,\n                            \"values\": [],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                36\n                            ]\n                        },\n                        \"Moment\": {\n                            \"notnull\": true,\n                            \"type\": \"object\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                {}\n                            ]\n                        },\n                        \"User\": {\n                            \"notnull\": true,\n                            \"type\": \"object\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                {\n                                    \"id@\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            14\n                                        ]\n                                    },\n                                    \"@column\": {\n                                        \"notnull\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            7\n                                        ]\n                                    }\n                                }\n                            ]\n                        },\n                        \"Comment[]\": {\n                            \"notnull\": true,\n                            \"type\": \"object\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                {\n                                    \"count\": {\n                                        \"notnull\": true,\n                                        \"type\": \"integer\",\n                                        \"valueLevel\": 0,\n                                        \"values\": [\n                                            3\n                                        ],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            1\n                                        ]\n                                    },\n                                    \"Comment\": {\n                                        \"notnull\": true,\n                                        \"type\": \"object\",\n                                        \"valueLevel\": 0,\n                                        \"values\": [\n                                            {\n                                                \"momentId@\": {\n                                                    \"notnull\": true,\n                                                    \"type\": \"string\",\n                                                    \"valueLevel\": 3,\n                                                    \"values\": [],\n                                                    \"lengthLevel\": 1,\n                                                    \"lengths\": [\n                                                        12\n                                                    ]\n                                                }\n                                            }\n                                        ]\n                                    }\n                                }\n                            ]\n                        }\n                    }\n                ]\n            }\n        }\n    ]\n}', '', '2022-07-14 23:08:52', NULL);
INSERT INTO `document` VALUES (1660136144185, 0, 0, 82031, NULL, 0, 3, NULL, '查询用户', 'SELECT', 'POST', 'JSON', '/get', '{\n    \"User\": {\n        \"id\": 82001\n    }\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"User\": {\n                \"notnull\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"id\": {\n                            \"notnull\": true,\n                            \"type\": \"integer\",\n                            \"valueLevel\": 1,\n                            \"values\": [\n                                82005,\n                                82001\n                            ],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                5\n                            ],\n                            \"trend\": {\n                                \"top\": 2,\n                                \"above\": 1,\n                                \"select\": \">=\",\n                                \"bottom\": 3\n                            }\n                        }\n                    }\n                ]\n            }\n        }\n    ]\n}', 'Authorization: Basic GERIJ2438R9FH239NW=  //取出 /login 接口返回的 token\nOther-Header: test', '2022-08-10 20:55:44', NULL);
