     \"lengths\": [\n                                        8\n                                    ],\n                                    \"repeat\": 7\n                                },\n                                \"itime\": {\n                                    \"notnull\": true,\n                                    \"type\": \"integer\",\n                                    \"valueLevel\": 1,\n                                    \"values\": [\n                                        1640707579\n                                    ],\n                                    \"lengthLevel\": 1,\n                                    \"lengths\": [\n                                        10\n                                    ],\n                                    \"repeat\": 14\n                                },\n                                \"custom_args\": {\n                                    \"notnull\": true,\n                                    \"type\": \"object\",\n                                    \"valueLevel\": 0,\n                                    \"values\": [\n                                        {}\n                                    ]\n                                },\n                                \"status\": {\n                                    \"notnull\": true,\n                                    \"type\": \"object\",\n                                    \"valueLevel\": 0,\n                                    \"values\": [\n                                        {\n                                            \"message_status\": {\n                                                \"notnull\": true,\n                                                \"type\": \"string\",\n                                                \"valueLevel\": 3,\n                                                \"values\": [],\n                                                \"lengthLevel\": 1,\n                                                \"lengths\": [\n                                                    9\n                                                ],\n                                                \"repeat\": 7\n                                            },\n                                            \"status_data\": {\n                                                \"notnull\": true,\n                                                \"type\": \"object\",\n                                                \"valueLevel\": 0,\n                                                \"values\": [\n                                                    {\n                                                        \"msg_time\": {\n                                                            \"notnull\": true,\n                                                            \"type\": \"integer\",\n                                                            \"valueLevel\": 1,\n                                                            \"values\": [\n                                                                1663432355\n                                                            ],\n                                                            \"lengthLevel\": 1,\n                                                            \"lengths\": [\n                                                                10\n                                                            ],\n                                                            \"repeat\": 14\n                                                        },\n                                                        \"channel_message_id\": {\n                                                            \"notnull\": true,\n                                                            \"type\": \"string\",\n                                                            \"valueLevel\": 3,\n                                                            \"values\": [],\n                       