                                                 },\n                                                        \"plan_user_total\": {\n                                                            \"notnull\": true,\n                                                            \"type\": \"integer\",\n                                                            \"valueLevel\": 0,\n                                                            \"values\": [\n                                                                2007\n                                                            ],\n                                                            \"lengthLevel\": 1,\n                                                            \"lengths\": [\n                                                                4\n                                                            ],\n                                                            \"repeat\": 14\n                                                        },\n                                                        \"country_code\": {\n                                                            \"notnull\": true,\n                                                            \"type\": \"string\",\n                                                            \"valueLevel\": 0,\n                                                            \"values\": [\n                                                                \"CN\"\n                                                            ],\n                                                            \"lengthLevel\": 1,\n                                                            \"lengths\": [\n                                                                2\n                                                            ],\n                                                            \"repeat\": 14\n                                                        },\n                                                        \"from_phone_id\": {\n                                                            \"notnull\": true,\n                                                            \"type\": \"string\",\n                                                            \"valueLevel\": 3,\n                                                            \"values\": [],\n                                                            \"lengthLevel\": 1,\n                                                            \"lengths\": [\n                                                                6\n                                                            ],\n                                                            \"repeat\": 7\n                                                        },\n                                                        \"conversation\": {\n                                                            \"notnull\": true,\n                                                            \"type\": \"object\",\n                                                            \"valueLevel\": 0,\n                                                            \"values\": [\n                                                                {\n                                                                    \"id\": {\n                                                                        \"notnull\": true,\n                                                                        \"type\": \"string\",\n                                                                        \"valueLevel\": 3,\n                                                                        \"values\": [],\n                                                                        \"lengthLevel\": 1,\n                                                                        \"lengths\": [\n                                                                            32\n                                            