"lengthLevel\": 1,\n                \"lengths\": []\n            },\n            \"format\": {\n                \"notnull\": true,\n                \"type\": \"boolean\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    false\n                ],\n                \"lengthLevel\": 1,\n                \"lengths\": []\n            },\n            \"defaults\": {\n                \"notnull\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"@database\": {\n                            \"notnull\": true,\n                            \"type\": \"string\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                \"MYSQL\"\n                            ],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                5\n                            ]\n                        },\n                        \"@schema\": {\n                            \"notnull\": true,\n                            \"type\": \"string\",\n                            \"valueLevel\": 3,\n                            \"values\": [],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                3\n                            ]\n                        }\n                    }\n                ]\n            }\n        }\n    ]\n}', 'https: //www.baidu.com/sugrec?&prod=pc_his&from=pc_web&json=1&sid=36557_39027_39024_38942_38881_38958_38955_38981_39017_38831_38917_38972_38808_38988_38640_26350_39041&hisdata=%5B%7B%22time%22%3A1688607061%2C%22kw%22%3A%22apiauto%22%7D%2C%7B%22time%22%3A1688609088%2C%22kw%22%3A%22aging%22%7D%2C%7B%22time%22%3A1688624878%2C%22kw%22%3A%22slq%E6%A0%BC%E5%BC%8F%E6%A3%80%E6%9F%A5%22%7D%2C%7B%22time%22%3A1688624885%2C%22kw%22%3A%22slq%E6%A0%BC%