INSERT INTO `document` VALUES (1704192205413, 0, 0, 82002, 'APIJSON.cn', 0, 4, NULL, 'method/invoke minus', NULL, NULL, 'JSON', '/method/invoke', '{\n    \"package\": \"unitauto.test\",\n    \"class\": \"testutil\",\n    \"method\": \"minus\",\n    \"args\": [\n        2,\n        3\n    ]\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"notempty\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"package\": {\n                \"notnull\": true,\n                \"notempty\": true,\n                \"type\": \"string\",\n                \"valueLevel\": 3,\n                \"format\": \"com.package\",\n                \"values\": [],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    13\n                ]\n            },\n            \"class\": {\n                \"notnull\": true,\n                \"notempty\": true,\n                \"type\": \"string\",\n                \"valueLevel\": 3,\n                \"format\": \"NAME:small\",\n                \"values\": [],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    8\n                ]\n            },\n            \"method\": {\n                \"notnull\": true,\n                \"notempty\": true,\n                \"type\": \"string\",\n                \"valueLevel\": 3,\n                \"format\": \"NAME:small\",\n                \"values\": [],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    5\n                ]\n            },\n            \"args\": {\n                \"notnull\": true,\n                \"notempty\": true,\n                \"type\": \"array\",\n                \"valueLevel\": 0,\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    2\n                ],\n                \"values\": [\n                    {\n                        \"notnull\": true,\n                        \"type\": \"integer\",\n                        \"valueLevel\": 0,\n                        \"values\": [\n                            3,\n                            2\n                        ],\n                        \"lengthLevel\": 1,\n                        \"lengths\": [\n                            1\n                        ],\n                        \"repeat\": 1\n                    }\n                ]\n            },\n            \"code\": {\n                \"notnull\": false,\n                \"type\": null,\n                \"guess\": true\n            }\n        }\n    ]\n}', '', '2024-01-17 15:27:59', NULL);
INSERT INTO `document` VALUES (1704192205414, 0, 0, 82002, 'APIJSON.cn', 0, 4, NULL, 'method/invoke comput_async', NULL, NULL, 'JSON', '/method/invoke', '{\n    \"package\": \"unitauto.test\",\n    \"class\": \"testutil\",\n    \"method\": \"compute_async\",\n    \"args\": [\n        2,\n        \"int:5\",\n        {\n            \"key\": \"callback\",\n            \"type\": \"def(a,b)\",\n            \"value\": {\n                \"callback\": true,\n                \"type\": \"int\",\n                \"return\": \"a - b\"\n            }\n        }\n    ]\n}', NULL, NULL, '{\n    \"notnull\": true,\n    \"notempty\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"package\": {\n                \"notnull\": true,\n                \"notempty\": true,\n                \"type\": \"string\",\n                \"valueLevel\": 3,\n                \"format\": \"com.package\",\n                \"values\": [],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    13\n                ]\n            },\n            \"class\": {\n                \"notnull\": true,\n                \"notempty\": true,\n                \"type\": \"string\",\n                \"valueLevel\": 3,\n                \"format\": \"NAME:small\",\n                \"values\": [],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    8\n                ]\n            },\n            \"method\": {\n                \"notnull\": true,\n                \"notempty\": true,\n                \"type\": \"string\",\n                \"valueLevel\": 3,\n                \"format\": \"NAME:small\",\n                \"values\": [],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    13\n                ]\n            },\n            \"args\": {\n                \"notnull\": true,\n                \"notempty\": true,\n                \"type\": \"array\",\n                \"valueLevel\": 0,\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    3\n                ],\n                \"values\": [\n                    {\n                        \"notnull\": true,\n                        \"type\": \"object\",\n                        \"valueLevel\": 3,\n                        \"values\": [\n                            2\n                        ],\n                        \"lengthLevel\": 1,\n                        \"lengths\": [\n                            5,\n                            1\n                        ],\n                        \"notempty\": true,\n                        \"format\": \"\"\n                    }\n                ]\n            },\n            \"code\": {\n                \"notnull\": false,\n                \"type\": null,\n                \"guess\": true\n            }\n        }\n    ]\n}', '', '2024-01-17 15:32:56', NULL);
INSERT INTO `document` VALUES (1704192205420, 0, 0, 82001, 'APIJSON.cn', 0, 3, NULL, '获取 评论及用户 的列表', 'SELECT', 'POST', 'JSON', '/get', '{\n    \"[]\": {\n        \"Comment\": {\n            \"momentId\": 15\n        },\n        \"User\": {\n            \"id@\": \"/Comment/userId\"\n        }\n    }\n}', NULL, NULL, '{\n    \"notNull\": true,\n    \"notEmpty\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"[]\": {\n                \"notNull\": true,\n                \"notEmpty\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"Comment\": {\n                            \"notNull\": true,\n                            \"notEmpty\": true,\n                            \"type\": \"object\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                {\n                                    \"momentId\": {\n                                        \"notNull\": true,\n                                        \"type\": \"integer\",\n                                        \"valueLevel\": 0,\n                                        \"values\": [\n                                            15\n                                        ],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            2\n                                        ]\n                                    }\n                                }\n                            ]\n                        },\n                        \"User\": {\n                            \"notNull\": true,\n                            \"notEmpty\": true,\n                            \"type\": \"object\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                {\n                                    \"id@\": {\n                                        \"notNull\": true,\n                                        \"notEmpty\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"format\": \"\",\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            15\n                                        ]\n                                    }\n                                }\n                            ]\n                        }\n                    }\n                ]\n            }\n        }\n    ]\n}', '', '2024-05-26 15:16:34', NULL);
INSERT INTO `document` VALUES (1704192205421, 0, 0, 82001, 'APIJSON', 82003, 3, NULL, '用户列表', 'SELECT', 'GET', 'PARAM', '/user/list', '{\n    \"pageSize\": 10,\n    \"pageNum\": 1,\n    \"searchKey\": \"a\"\n}', NULL, NULL, '{\n    \"notNull\": true,\n    \"notEmpty\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"pageSize\": {\n                \"notNull\": true,\n                \"type\": \"integer\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    10\n                ],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    2\n                ],\n                \"comment\": \"每页数量\"\n            },\n            \"pageNum\": {\n                \"notNull\": true,\n                \"type\": \"integer\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    1\n                ],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    1\n                ]\n            },\n            \"searchKey\": {\n                \"notNull\": true,\n                \"notEmpty\": true,\n                \"type\": \"string\",\n                \"valueLevel\": 3,\n                \"format\": \"NAME:small\",\n                \"values\": [],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    1\n                ],\n                \"comment\": \"搜索关键词\"\n            }\n        }\n    ]\n}', NULL, '2024-06-04 10:15:31', '');
INSERT INTO `document` VALUES (1704192205422, 0, 0, 82001, 'APIJSON', 82003, 3, NULL, '用户详情', NULL, 'GET', 'PARAM', '/user', '{\n    \"id\": 82001\n}', NULL, NULL, '{\n    \"notNull\": true,\n    \"notEmpty\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"id\": {\n                \"notNull\": true,\n                \"type\": \"integer\",\n                \"valueLevel\": 1,\n                \"values\": [\n                    82001\n                ],\n                \"lengthLevel\": 1,\n                \"lengths\": [\n                    5\n                ],\n                \"comment\": \"主键\"\n            }\n        }\n    ]\n}', NULL, '2024-06-04 10:15:31', '');
INSERT INTO `document` VALUES (1704192205423, 0, 0, 82001, 'APIJSON.cn', 0, 3, NULL, '测试001', 'SELECT', 'POST', 'JSON', '/get', '{\n    \"User\": {\n        \"id\": 82001\n    },\n    \"[]\": {\n        \"Comment\": {\n            \"userId@\": \"User/id\"\n        }\n    }\n}', NULL, NULL, '{\n    \"notNull\": true,\n    \"notEmpty\": true,\n    \"type\": \"object\",\n    \"valueLevel\": 0,\n    \"values\": [\n        {\n            \"User\": {\n                \"notNull\": true,\n                \"notEmpty\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"0\": {\n                            \"type\": \"object\",\n                            \"notNull\": true,\n                            \"comment\": \"以上查一个对象，以下查一个数组，Comment.userId = User.id。在键值对后按 Enter 回车键自动智能生成补全提示\"\n                        },\n                        \"id\": {\n                            \"notNull\": true,\n                            \"type\": \"integer\",\n                            \"valueLevel\": 1,\n                            \"values\": [\n                                82001\n                            ],\n                            \"lengthLevel\": 1,\n                            \"lengths\": [\n                                5\n                            ]\n                        }\n                    }\n                ]\n            },\n            \"[]\": {\n                \"notNull\": true,\n                \"notEmpty\": true,\n                \"type\": \"object\",\n                \"valueLevel\": 0,\n                \"values\": [\n                    {\n                        \"Comment\": {\n                            \"notNull\": true,\n                            \"notEmpty\": true,\n                            \"type\": \"object\",\n                            \"valueLevel\": 0,\n                            \"values\": [\n                                {\n                                    \"userId@\": {\n                                        \"notNull\": true,\n                                        \"notEmpty\": true,\n                                        \"type\": \"string\",\n                                        \"valueLevel\": 3,\n                                        \"format\": \"root/folder\",\n                                        \"values\": [],\n                                        \"lengthLevel\": 1,\n                                        \"lengths\": [\n                                            7\n                                        ]\n                                    }\n                                }\n                            ]\n                        }\n                    }\n                ]\n            }\n        }\n    ]\n}', '', '2024-06-04 13:52:45', '\n以上 JSON 文本支持 JSON5 格式。清空文本内容可查看规则。\n注释可省略。行注释前必须有 1 个空格；段注释必须在 JSON 下方。\n\n## 快捷键\nCtrl + I 或 Command + I 格式化输入框，清除所有注释和无效空格、换行等；\nCtrl + / 或 Command + / 对选中行 新增行注释 或 取消行注释；\nCtrl + D 或 Command + D 删除 选中行；\nCtrl + S 或 Command + S 保存当前用例；\n\n#### 右上角设置项 > 预览请求输入框，显示对应的预览效果');
INSERT INTO `function` VALUES (3, 0, 0, NULL, 'countArray', 'int', 'array', '{\"array\": [1, 2, 3]}', '获取数组长度。没写调用键值对，会自动补全 \"result()\": \"countArray(array)\"', 0, NULL, NULL, '2018-10-13 16:23:23', NULL);
INSERT INTO `function` VALUES (4, 0, 0, NULL, 'countObject', 'int', 'object', '{\"object\": {\"key0\": 1, \"key1\": 2}}', '获取对象长度。', 0, NULL, NULL, '2018-10-13 16:23:23', NULL);
INSERT INTO `function` VALUES (5, 0, 0, NULL, 'isContain', 'boolean', 'array,value', '{\"array\": [1, 2, 3], \"value\": 2}', '判断是否数组包含值。', 0, NULL, NULL, '2018-10-13 16:23:23', NULL);
INSERT INTO `function` VALUES (6, 0, 0, NULL, 'isContainKey', 'boolean', 'object,key', '{\"key\": \"id\", \"object\": {\"id\": 1}}', '判断是否对象包含键。', 0, NULL, NULL, '2018-10-13 16:30:31', NULL);
INSERT INTO `function` VALUES (7, 0, 0, NULL, 'isContainValue', 'boolean', 'object,value', '{\"value\": 1, \"object\": {\"id\": 1}}', '判断是否对象包含值。', 0, NULL, NULL, '2018-10-13 16:30:31', NULL);
INSERT INTO `function` VALUES (8, 0, 0, NULL, 'getFromArray', 'Object', 'array,position', '{\"array\": [1, 2, 3], \"result()\": \"getFromArray(array,1)\"}', '根据下标获取数组里的值。position 传数字时直接作为值，而不是从所在对象 request 中取值', 0, NULL, NULL, '2018-10-13 16:30:31', NULL);
INSERT INTO `function` VALUES (9, 0, 0, NULL, 'getFromObject', 'Object', 'object,key', '{\"key\": \"id\", \"object\": {\"id\": 1}}', '根据键获取对象里的值。', 0, NULL, NULL, '2018-10-13 16:30:31', NULL);
INSERT INTO `function` VALUES (10, 0, 0, NULL, 'deleteCommentOfMoment', 'int', 'momentId', '{\"momentId\": 1}', '根据动态 id 删除它的所有评论', 0, 'Moment', 'DELETE', '2019-08-18 02:46:56', NULL);
INSERT INTO `function` VALUES (11, 0, 0, NULL, 'verifyIdList', NULL, 'array', '{\"array\": [1, 2, 3], \"result()\": \"verifyIdList(array)\"}', '校验类型为 id 列表', 0, NULL, NULL, '2019-08-18 03:58:33', NULL);
INSERT INTO `function` VALUES (12, 0, 0, NULL, 'verifyURLList', NULL, 'array', '{\"array\": [\"http://123.com/1.jpg\", \"http://123.com/a.png\", \"http://www.abc.com/test.gif\"], \"result()\": \"verifyURLList(array)\"}', '校验类型为 URL 列表', 0, NULL, NULL, '2019-08-18 03:58:33', NULL);
INSERT INTO `function` VALUES (13, 0, 0, NULL, 'getWithDefault', 'Object', 'value,defaultValue', '{\"value\": null, \"defaultValue\": 1}', '如果 value 为 null，则返回 defaultValue', 0, NULL, NULL, '2019-08-20 23:26:36', NULL);
INSERT INTO `function` VALUES (14, 0, 0, NULL, 'removeKey', 'Object', 'key', '{\"key\": \"s\", \"key2\": 2}', '从对象里移除 key', 0, NULL, NULL, '2019-08-20 23:26:36', NULL);
INSERT INTO `function` VALUES (15, 0, 0, NULL, 'getFunctionDemo', 'JSONObject', NULL, '{}', '获取远程函数的 Demo', 0, NULL, NULL, '2019-08-20 23:26:36', NULL);
INSERT INTO `function` VALUES (16, 0, 0, NULL, 'getFunctionDetail', 'String', NULL, '{}', '获取远程函数的详情', 0, NULL, NULL, '2019-08-20 23:26:36', NULL);
