INSERT INTO `request` VALUES (1, 0, 1, 'POST', 'register', '{\"User\": {\"MUST\": \"name\", \"REFUSE\": \"id\", \"UPDATE\": {\"id@\": \"Privacy/id\"}}, \"Privacy\": {\"MUST\": \"_password,phone\", \"REFUSE\": \"id\", \"UNIQUE\": \"phone\", \"VERIFY\": {\"phone~\": \"PHONE\"}}}', 'UNIQUE校验phone是否已存在。VERIFY校验phone是否符合手机号的格式', '2017-02-01 19:19:51');
INSERT INTO `request` VALUES (2, 0, 1, 'POST', 'Moment', '{\"INSERT\": {\"@role\": \"OWNER\", \"pictureList\": [], \"praiseUserIdList\": []}, \"REFUSE\": \"id\", \"UPDATE\": {\"verifyIdList-()\": \"verifyIdList(praiseUserIdList)\", \"verifyURLList-()\": \"verifyURLList(pictureList)\"}}', 'INSERT当没传pictureList和praiseUserIdList时用空数组[]补全，保证不会为null', '2017-02-01 19:19:51');
INSERT INTO `request` VALUES (3, 0, 1, 'POST', 'Comment', '{\"MUST\": \"momentId,content\", \"REFUSE\": \"id\", \"UPDATE\": {\"@role\": \"OWNER\"}}', '必须传userId,momentId,content，不允许传id', '2017-02-01 19:19:51');
INSERT INTO `request` VALUES (4, 0, 1, 'PUT', 'User', '{\"MUST\": \"id\", \"INSERT\": {\"@role\": \"OWNER\"}, \"REFUSE\": \"phone\"}', '必须传id，不允许传phone。INSERT当没传@role时用OWNER补全', '2017-02-01 19:19:51');
INSERT INTO `request` VALUES (5, 0, 1, 'DELETE', 'Moment', '{\"Moment\": {\"MUST\": \"id\", \"INSERT\": {\"@role\": \"OWNER\"}, \"UPDATE\": {\"commentCount()\": \"deleteCommentOfMoment(id)\"}}}', NULL, '2017-02-01 19:19:51');
INSERT INTO `request` VALUES (6, 0, 1, 'DELETE', 'Comment', '{\"MUST\": \"id\", \"INSERT\": {\"@role\": \"OWNER\"}, \"UPDATE\": {\"childCount()\": \"deleteChildComment(id)\"}}', 'disallow没必要用于DELETE', '2017-02-01 19:19:51');
