INSERT INTO `request` VALUES (14, 0, 1, 'POST', 'Verify', '{\"MUST\": \"phone,verify\", \"REFUSE\": \"!\"}', '必须传phone,verify，其它都不允许传', '2017-02-18 22:20:43');
