INSERT INTO `testrecord` VALUES (1657044803870, 0, 0, 82001, 0, 0, 0, 1522905263828, 0, 0, 'http://apijson.cn:8080', '2022-07-06 02:13:23', NULL, NULL, NULL, '{\"Moment\":{\"id\":120,\"@role\":\"OWNER\",\"commentCount()\":\"deleteCommentOfMoment(id)\"},\"ok\":false,\"msg\":\"没权限访问或对象不存在！\",\"debug:info|help\":\"|   \\n 浏览器打开以下链接查看解答\\n【APIAuto】： \\n http://apijson.cn/api?type=JSON&url=http%3A%2F%2Fapijson.cn%3A8080%2Fdelete&json=%7B%22Moment%22%3A%7B%22id%22%3A120%2C%22%40role%22%3A%22OWNER%22%2C%22commentCount%28%29%22%3A%22deleteCommentOfMoment%28id%29%22%7D%7D        \\n\\n【GitHub】： \\n https://www.google.com/search?q=site%3Agithub.com%2FTencent%2FAPIJSON+++%E6%B2%A1%E6%9D%83%E9%99%90%E8%AE%BF%E9%97%AE%E6%88%96%E5%AF%B9%E8%B1%A1%E4%B8%8D%E5%AD%98%E5%9C%A8%EF%BC%81        \\n\\n【Google】：\\n https://www.google.com/search?q=%E6%B2%A1%E6%9D%83%E9%99%90%E8%AE%BF%E9%97%AE%E6%88%96%E5%AF%B9%E8%B1%A1%E4%B8%8D%E5%AD%98%E5%9C%A8%EF%BC%81        \\n\\n【百度】：\\n https://www.baidu.com/s?ie=UTF-8&wd=%E6%B2%A1%E6%9D%83%E9%99%90%E8%AE%BF%E9%97%AE%E6%88%96%E5%AF%B9%E8%B1%A1%E4%B8%8D%E5%AD%98%E5%9C%A8%EF%BC%81        \\n\\n都没找到答案？打开这个链接 \\n https://github.com/Tencent/APIJSON/issues/new?assignees=&labels=&template=--bug.md   \\n然后提交问题，推荐用以下模板修改，注意要换行保持清晰可读。 \\n【标题】：没权限访问或对象不存在！ \\n【内容】：**环境信息**  \\n 系统: Linux 3.10.0-957.27.2.el7.x86_64 \\n 数据库: MYSQL 5.7.22 \\n JDK: 1.8.0_181 amd64 \\n APIJSON: 5.0.0\\n\\n**问题描述**\\n没权限访问或对象不存在！ \\n\\n<!-- 尽量完整截屏(至少包含请求和回包结果，还可以加上控制台报错日志)，然后复制粘贴到这里 --> \\n\\nPOST http://apijson.cn:8080/delete \\n请求 Request JSON：\\n ```js \\n 请填写，例如 { \\\"Users\\\":{} } \\n``` \\n\\n返回结果 Response JSON：\\n ```js \\n 请填写，例如 { \\\"Users\\\": {}, \\\"code\\\": 401, \\\"msg\\\": \\\"Users 不允许 UNKNOWN 用户的 GET 请求！\\\" } \\n```\",\"trace:throw\":\"java.lang.IllegalAccessException\",\"code\":401}', '{\"code\":4,\"msg\":\"没有校验标准，且状态码在 [400, 599] 内或不是 0, 200 等以 0 结尾的数\",\"path\":\"\",\"duration\":\"很快：比以往 [20ms, 200ms] 最快还更快\"}', '{\"notnull\":true,\"type\":\"object\",\"valueLe