  `_payPassword` int NOT NULL DEFAULT 123456 COMMENT '支付密码',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `phone_UNIQUE`(`phone` ASC) USING BTREE,
  INDEX `index_phone`(`phone` ASC) USING BTREE,
  INDEX `index_phone_password`(`phone` ASC, `_password` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1704867024922 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '用户隐私信息表。\n对安全要求高，不想泄漏真实名称。对外名称为 Privacy' ROW_FORMAT = Dynamic;

